.no-match { padding: var(--space-4); color: var(--text); }
.sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
.orders { width: 100%; border-collapse: collapse; background: var(--surface); color: var(--text); }
.orders th, .orders td { padding: var(--space-2) var(--space-3, var(--space-2)); text-align: left; border-bottom: var(--border-width) solid var(--border); vertical-align: middle; }
.orders .num { text-align: right; }
.badge { display: inline-block; padding: 2px var(--space-2); border: var(--border-width) solid var(--border); border-radius: var(--radius-card); }
.row-actions { display: flex; gap: var(--space-2); flex-wrap: wrap; }
.dialog { width: min(440px, calc(100vw - 32px)); max-height: calc(100vh - 32px); padding: 0; border: var(--border-width) solid var(--border); border-radius: var(--radius-card); background: var(--surface); color: var(--text); }
.dialog::backdrop { background: rgb(0 0 0 / 0.5); }
