.dialog-body h2 { margin: 0; font-size: var(--type-title-size); font-weight: var(--type-title-weight); }
.dialog-body p { margin: 0; }
.actions { display: flex; justify-content: flex-end; gap: var(--space-2); flex-wrap: wrap; }

@media (max-width: 720px) {
  .toolbar { grid-template-columns: minmax(0, 1fr); }
