  .orders td { display: flex; justify-content: space-between; gap: var(--space-4); text-align: right; overflow-wrap: anywhere; }
  .orders td[data-label]::before { content: attr(data-label); text-align: left; font-weight: 600; flex-shrink: 0; }
  .orders td.row-actions { justify-content: flex-end; }
}

